            if (!emo && ag) {
                for (int i = int(m.wm.affects.size()) - 1; i >= 0; --i) {
                    if (m.wm.affects[i].agent == ag) {
                        emo = m.gpu_appraise_emotion(m.wm.affects[i].event_act, &tr);
                        break;
                    }
                }
            }
