        m.wm.last_answer_concept = chain.back(); m.wm.last_confidence = 96;
        m.wm.last_provenance = PROV_CONSOLIDATED; tr.confidence = 96;
        tb.reply_kind = REP_THINK_CHAIN; tb.seq = chain;
