        tb.reply_kind = REP_ACK; tb.subj = p.subj ? p.subj : m.markers[LM_BUDGET]; tb.rel = rel_has;
        tb.obj = p.qty != QTY_NONE ? m.perceive_word(std::to_string(p.qty), true, CAT_NUMBER, &tr) : 0;
        return broca_speak(m, tb, &tr);
