        m.wm.last_confidence = 99; tr.confidence = 99; ++tr.reasoning_hops;
        int ans = 0;
        if (p.modifiers == 0u) ans = pr.vy / pr.g;
        else if (p.modifiers == 1u) ans = (pr.vy * pr.vy) / (2 * pr.g);
        else ans = pr.vx * ((2 * pr.vy) / pr.g);
        m.wm.last_solved_num = ans;
        tb.reply_kind = REP_ARITH; tb.qty = ans;
        return broca_speak(m, tb, &tr);
