        m.wm.last_answer_concept = end_c;
        m.wm.last_confidence = 99; tr.confidence = 99;
        tb.reply_kind = REP_CHAINRULE_EXEC; tb.subj = mid_c; tb.obj = end_c;
        return broca_speak(m, tb, &tr);
