        m.wm.last_confidence = 99; tr.confidence = 99; ++tr.reasoning_hops;
        int ans = (p.modifiers == 0u) ? v2 : ((vr.rho * (v2 * v2 - vr.v1 * vr.v1)) / 2);
        m.wm.last_solved_num = ans; tb.reply_kind = REP_ARITH; tb.qty = ans;
        return broca_speak(m, tb, &tr);
